{
  "passageId": "corporate-law",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법인이 독립된 권리·의무의 주체라는 법적 지위로부터 자산 소유권의 귀속에 관한 판단이 도출된다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "법인에게 행위 능력이 없다는 한계를 보완하도록 권한을 부여받은 사람이 자산을 운용하는 방식이 제시된다."
    },
    {
      "id": "R3",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "권한을 부여받아 자산을 운용하더라도 절차와 목적을 위반하면 처벌받을 수 있다는 권한 행사의 한계를 제시한다."
    },
    {
      "id": "R4",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "자산 운용에 대한 법적 통제를 공동체 질서 유지라는 목적을 위한 수단으로 설명한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "재단 법인과 사단 법인의 일반적 구분을 장학 재단이라는 구체적 사례로 보여 준다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "영리성에 따른 법인 구분을 비영리 법인인 장학 재단의 사례로 구체화한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "비영리 법인이라는 분류와 그 정의를 근거로 장학 재단이 경제적 이익을 추구하지 않는다는 판단을 도출한다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "재단 법인이라는 분류와 그 정의로부터 장학 재단의 법인격이 자산 자체에 부여된다는 설명이 따라 나온다."
    },
    {
      "id": "R9",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "법인의 행위 능력 부재를 보완하기 위한 제도적 장치로 이사회가 설치된다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "이사회가 결정권자가 아니라는 설명을 주요 사항에 관할 기관의 허가가 필요하다는 구체적 요건으로 풀어 준다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주요 사항에 허가가 필요하다는 설명을 기본 재산의 처분이나 용도 변경이라는 구체적 경우로 보여 준다."
    },
    {
      "id": "R12",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "수익 추구가 허용되더라도 영리 목적이 아니라 목적 사업의 재원 마련에 한정된다는 한계를 제시한다."
    },
    {
      "id": "R13",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "기본 재산과 그 밖의 자산을 운용 요건이라는 같은 기준에서 비교하여 차이를 제시한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법인 종류에 따라 통제 내용이 다르다는 일반적 설명을 주식회사의 법적 통제 사례로 구체화한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "구체적인 요건과 절차를 규정한 상법도 적용된다는 사실을 근거로 통제가 더 정교하다는 평가를 도출한다."
    },
    {
      "id": "R16",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "장학 재단과 주식회사를 법인격의 부여 대상이라는 같은 기준에서 비교한다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "재단 법인과 주식회사의 자산 운용 주체가 행사할 수 있는 결정권의 차이를 비교한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "개인의 출자로 형성되는 법인 자산을 주주의 출자로 형성되는 주식회사 자산이라는 구체적 사례로 보여 준다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자본금이 지급 능력과 재무 안정성을 보장한다는 기능을 근거로 감액 금지 원칙을 설명한다."
    },
    {
      "id": "R20",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "이익 잉여금과 자본 잉여금을 재원의 발생 경로와 사용 가능 범위라는 기준에서 비교한다."
    },
    {
      "id": "R21",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "자본금 감액 금지라는 원칙에 대해 잉여금으로 손실을 보전할 수 없는 경우의 예외를 제시한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자본금 감소가 회사 존립을 위태롭게 한다는 위험을 이유로 신중하게 운용해야 한다는 당위를 뒷받침한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주식회사의 자산 운용 통제가 정교하다는 설명을 무상 증자와 배당의 실행 요건 차이로 구체화한다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "재무 구조가 안정적이라는 인상이 실제로 주가 상승을 유발할 수 있다는 작용을 설명한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "무상 증자가 자산 총규모를 바꾸지 않는다는 사실을 근거로 이사회 결정만으로 실행 가능한 이유를 설명한다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "배당이 자산의 외부 유출을 수반한다는 사실을 이유로 더 까다로운 요건을 충족해야 한다는 당위를 설명한다."
    },
    {
      "id": "R27",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "까다로운 배당 실행 요건이 회사나 주주의 손해 방지라는 목적을 위해 마련되었음을 설명한다."
    },
    {
      "id": "R28",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "무상 증자와 배당을 자산의 외부 유출 여부 및 실행 요건이라는 같은 기준에서 비교한다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "배당이라는 동일한 대상에 대해 기본적인 뜻에 이어 기대 효과와 실행 요건을 더 자세히 설명한다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법적 통제의 일반적 목적을 배당에서 회사와 주주의 손해를 방지한다는 구체적 목적으로 보여 준다."
    }
  ]
}

